SELECT stddev(p.systolic_blood_pressure) AS standard_deviation FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN labevents l ON a.subject_id = l.subject_id WHERE p.gender = 'M' AND p.anchor_age = 81 AND EXTRACT(YEAR FROM l.charttime) = 2020 AND EXTRACT(MONTH FROM l.charttime) = 1 AND EXTRACT(DAY FROM l.charttime) BETWEEN 1 AND 24 AND p.anchor_year BETWEEN 76 AND 86 AND l.itemid = 848075 AND l.valueuom = 'mmHg' AND l.value BETWEEN 100 AND 200;